export type Mode = 'keyboard' | 'suggestion';
export type AlphabetKey = 'polish' | 'nato';

export interface AlphabetEntry {
  symbol: string;
  codeword: string;
}

export interface RunState {
  alphabet: AlphabetKey;
  mode: Mode;
  questions: AlphabetEntry[];
  currentIndex: number;
  hintedIndices: Set<number>;
  finished: boolean;
}

/** Fisher-Yates shuffle */
export function shuffleArray<T>(arr: T[]): T[] {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export function normalizeAnswer(input: string): string {
  return input.trim();
}

export function answersMatch(input: string, expected: string): boolean {
  return normalizeAnswer(input).toLowerCase() === expected.toLowerCase();
}

export function computeScore(total: number, hinted: number): number {
  return Math.round(((total - hinted) / total) * 100);
}
