import { t } from "../i18n.ts";
import { getOptions } from "../data.ts";
import { shuffleArray, answersMatch } from "../model.ts";
import type { RunState } from "../model.ts";

interface RunDeps {
  runState: RunState;
  goToResult: (runState: RunState) => void;
  goToSetup: () => void;
}

export function RunScreen(container: HTMLElement, deps: RunDeps) {
  const { runState, goToResult, goToSetup } = deps;
  const current = runState.questions[runState.currentIndex];
  const total = runState.questions.length;
  const shownHint = runState.hintedIndices.has(runState.currentIndex);

  const wrap = document.createElement("div");
  wrap.className = "screen run-screen";

  wrap.innerHTML = `
    <div class="run-header">
      <button type="button" class="back-btn">${t("back")}</button>
      <span class="progress">${t("questionProgress", { current: runState.currentIndex + 1, total })}</span>
    </div>
    <div class="question">
      <div class="symbol">${current.symbol}</div>
      <div class="hint-area"></div>
      <div class="feedback"></div>
      <div class="input-area"></div>
      <button type="button" class="hint-btn">${t("hint")}</button>
    </div>
  `;

  const backBtn = wrap.querySelector(".back-btn") as HTMLButtonElement;
  const hintArea = wrap.querySelector(".hint-area") as HTMLDivElement;
  const feedback = wrap.querySelector(".feedback") as HTMLDivElement;
  const inputArea = wrap.querySelector(".input-area") as HTMLDivElement;
  const hintBtn = wrap.querySelector(".hint-btn") as HTMLButtonElement;

  function showHint() {
    runState.hintedIndices.add(runState.currentIndex);
    hintArea.textContent = current.codeword;
    hintArea.classList.add("visible");
    hintBtn.disabled = true;
  }

  if (shownHint) showHint();

  hintBtn.addEventListener("click", () => showHint());

  backBtn.addEventListener("click", () => {
    const ok = confirm(
      runState.mode === "keyboard"
        ? "Quit the current run?"
        : "Zakończyć bieżący przebieg?",
    );
    if (ok) goToSetup();
  });

  function advance() {
    feedback.textContent = t("correct");
    feedback.className = "feedback correct";
    setTimeout(() => {
      if (runState.currentIndex + 1 >= total) {
        runState.finished = true;
        goToResult(runState);
      } else {
        runState.currentIndex += 1;
        RunScreen(container, deps); // rebuild
      }
    }, 500);
  }

  function wrongFeedback() {
    feedback.textContent = t("wrong");
    feedback.className = "feedback wrong";
  }

  // Mode-specific UI
  if (runState.mode === "keyboard") {
    const form = document.createElement("form");
    form.className = "keyboard-form";
    form.innerHTML = `
      <input type="text" class="answer-input" placeholder="${t("enterAnswer")}" autocomplete="off" />
      <button type="submit" class="submit-btn">${t("submit")}</button>
    `;
    const input = form.querySelector(".answer-input") as HTMLInputElement;
    form.addEventListener("submit", (e) => {
      e.preventDefault();
      if (answersMatch(input.value, current.codeword)) {
        advance();
      } else {
        wrongFeedback();
      }
    });
    inputArea.appendChild(form);
    input.focus();
  } else {
    const options = shuffleArray(getOptions(runState.alphabet, current.symbol));
    const grid = document.createElement("div");
    grid.className = "suggestion-grid";
    options.forEach((opt) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "option-btn";
      btn.textContent = opt;
      btn.addEventListener("click", () => {
        if (opt === current.codeword) {
          advance();
        } else {
          wrongFeedback();
        }
      });
      grid.appendChild(btn);
    });
    inputArea.appendChild(grid);
  }

  container.innerHTML = "";
  container.appendChild(wrap);
}
