import alphabetData from '../benchmark-data/alphabets.json';
import optionsData from '../benchmark-data/multiple-choice-options.json';
import type { AlphabetEntry, AlphabetKey } from './model.ts';

export function getAlphabet(key: AlphabetKey): AlphabetEntry[] {
  return alphabetData[key] as AlphabetEntry[];
}

export function getOptions(key: AlphabetKey, symbol: string): string[] {
  const list = optionsData[key] as Record<string, string[]>;
  return list[symbol];
}
