import { t, getLang, setLang, type Lang } from "../i18n.ts";
import { getAlphabet } from "../data.ts";
import { shuffleArray } from "../model.ts";
import type { AlphabetKey, Mode, RunState } from "../model.ts";

const implementationDate = "2026-05-29";

interface SetupDeps {
  goToRun: (runState: RunState) => void;
}

export function SetupScreen(container: HTMLElement, deps: SetupDeps) {
  let selectedLang: Lang = getLang();
  let selectedAlphabet: AlphabetKey = "polish";
  let selectedMode: Mode = "keyboard";

  const wrap = document.createElement("div");
  wrap.className = "screen setup-screen";

  wrap.innerHTML = `
    <header class="app-header"><h1>${t("appTitle")}</h1></header>
    <form class="setup-form">
      <fieldset>
        <legend>${t("chooseLanguage")}</legend>
        <div class="choice-row">
          <button type="button" class="choice-btn lang-btn" data-lang="en">English</button>
          <button type="button" class="choice-btn lang-btn" data-lang="pl">Polski</button>
        </div>
      </fieldset>

      <fieldset>
        <legend>${t("chooseAlphabet")}</legend>
        <div class="choice-row">
          <button type="button" class="choice-btn alphabet-btn" data-alphabet="polish">${t("polish")}</button>
          <button type="button" class="choice-btn alphabet-btn" data-alphabet="nato">${t("nato")}</button>
        </div>
        <p class="alphabet-desc"></p>
      </fieldset>

      <fieldset>
        <legend>${t("chooseMode")}</legend>
        <div class="choice-row">
          <button type="button" class="choice-btn mode-btn" data-mode="keyboard">${t("keyboard")}</button>
          <button type="button" class="choice-btn mode-btn" data-mode="suggestion">${t("suggestion")}</button>
        </div>
        <p class="mode-desc"></p>
      </fieldset>

      <button type="submit" class="start-btn">${t("start")}</button>
    </form>
    <footer class="attribution">${t("attribution", { date: implementationDate })}</footer>
  `;

  const langBtns = wrap.querySelectorAll(
    ".lang-btn",
  ) as NodeListOf<HTMLButtonElement>;
  const alphabetBtns = wrap.querySelectorAll(
    ".alphabet-btn",
  ) as NodeListOf<HTMLButtonElement>;
  const modeBtns = wrap.querySelectorAll(
    ".mode-btn",
  ) as NodeListOf<HTMLButtonElement>;
  const alphabetDesc = wrap.querySelector(
    ".alphabet-desc",
  ) as HTMLParagraphElement;
  const modeDesc = wrap.querySelector(".mode-desc") as HTMLParagraphElement;

  function updateUI() {
    langBtns.forEach((btn) =>
      btn.classList.toggle("active", btn.dataset.lang === selectedLang),
    );
    alphabetBtns.forEach((btn) =>
      btn.classList.toggle("active", btn.dataset.alphabet === selectedAlphabet),
    );
    modeBtns.forEach((btn) =>
      btn.classList.toggle("active", btn.dataset.mode === selectedMode),
    );
    alphabetDesc.textContent =
      selectedAlphabet === "polish"
        ? t("polishAlphabetLabel")
        : t("natoAlphabetLabel");
    modeDesc.textContent =
      selectedMode === "keyboard"
        ? t("keyboardModeLabel")
        : t("suggestionModeLabel");

    // Re-apply translations to dynamic copy
    const startBtn = wrap.querySelector(".start-btn") as HTMLButtonElement;
    startBtn.textContent = t("start");
  }

  langBtns.forEach((btn) =>
    btn.addEventListener("click", () => {
      selectedLang = btn.dataset.lang as Lang;
      setLang(selectedLang);
      // Rebuild the whole screen to refresh all translations
      container.innerHTML = "";
      SetupScreen(container, deps);
    }),
  );

  alphabetBtns.forEach((btn) =>
    btn.addEventListener("click", () => {
      selectedAlphabet = btn.dataset.alphabet as AlphabetKey;
      updateUI();
    }),
  );

  modeBtns.forEach((btn) =>
    btn.addEventListener("click", () => {
      selectedMode = btn.dataset.mode as Mode;
      updateUI();
    }),
  );

  const form = wrap.querySelector(".setup-form") as HTMLFormElement;
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const alphabetEntries = getAlphabet(selectedAlphabet);
    const runState: RunState = {
      alphabet: selectedAlphabet,
      mode: selectedMode,
      questions: shuffleArray(alphabetEntries),
      currentIndex: 0,
      hintedIndices: new Set(),
      finished: false,
    };
    deps.goToRun(runState);
  });

  // Start with both first options active by default
  updateUI();
  container.appendChild(wrap);
}
