import { t } from '../i18n.ts';
import { computeScore } from '../model.ts';
import type { RunState } from '../model.ts';

interface ResultDeps {
  runState: RunState;
  goToSetup: () => void;
}

export function ResultScreen(container: HTMLElement, deps: ResultDeps) {
  const { runState, goToSetup } = deps;
  const total = runState.questions.length;
  const hinted = runState.hintedIndices.size;
  const score = computeScore(total, hinted);

  const wrap = document.createElement('div');
  wrap.className = 'screen result-screen';

  wrap.innerHTML = `
    <header class="app-header"><h1>${t('appTitle')}</h1></header>
    <div class="result-card">
      <h2>${t('resultTitle')}</h2>
      <p class="score">${t('score', { score })}</p>
      <p>${t('resultAlphabet', { alphabet: t(runState.alphabet) })}</p>
      <p>${t('resultMode', { mode: t(runState.mode) })}</p>
      <button type="button" class="restart-btn">${t('restart')}</button>
    </div>
  `;

  const restartBtn = wrap.querySelector('.restart-btn') as HTMLButtonElement;
  restartBtn.addEventListener('click', () => goToSetup());

  container.innerHTML = '';
  container.appendChild(wrap);
}
