import "./styles.css";
import { setLang } from "./i18n.ts";
import { SetupScreen } from "./screens/SetupScreen.ts";
import { RunScreen } from "./screens/RunScreen.ts";
import { ResultScreen } from "./screens/ResultScreen.ts";
import type { RunState } from "./model.ts";

type Screen = "setup" | "run" | "result";

interface AppState {
  screen: Screen;
  runState?: RunState;
}

const app = document.getElementById("app");
if (!app) throw new Error("#app not found");
const container = app; // narrowed

const state: AppState = { screen: "setup" };

function clear() {
  container.innerHTML = "";
}

export function goToSetup() {
  state.screen = "setup";
  state.runState = undefined;
  clear();
  SetupScreen(container, { goToRun });
}

export function goToRun(runState: RunState) {
  state.screen = "run";
  state.runState = runState;
  clear();
  RunScreen(container, { runState, goToResult, goToSetup });
}

export function goToResult(runState: RunState) {
  state.screen = "result";
  state.runState = runState;
  clear();
  ResultScreen(container, { runState, goToSetup });
}

// Initialize with default language
setLang("en");
goToSetup();
